  var perm = new Uint8Array(16);
  for (var q = 0; q < 16; q++) perm[q] = q;
  for (var k = 15; k > 0; k--) {
    var j = rnd() % (k + 1);
    var t = perm[k];
    perm[k] = perm[j];
    perm[j] = t;
  }
  var impl = MS_vmHandlers();
  var handlers = new Array(16);
  for (var op2 = 0; op2 < 16; op2++) handlers[perm[op2]] = impl[op2];
  var code = new Uint8Array(n);
  for (var c = 0; c < n; c++) code[c] = perm[ops[c]];
