  var sealMaterial = MS_hkdf(session.psk, 'offer', 32);
  var opened = MS_mixedOpen(sealMaterial, nonce, offer.box, offer.boxVariant);
  if (opened === null) return { ok: false, reason: 'MS:offer-decode' };
  var remoteText = MS_fromBytes(opened);
  if (remoteText !== offer.eph || remoteText.length !== 64 || opened.length !== 64) return { ok: false, reason: 'MS:offer-box' };
  var expected = MS_mac(MS_hsMacKey(session), [MS_toBytes(offer.id), opened, MS_toBytes(offer.box)]);
  if (!MS_constantTimeEqual(expected, MS_hexToBytes(offer.mac))) return { ok: false, reason: 'MS:offer-mac' };
  session.remote = remoteText;
  session.root = MS_hsShared(session, remoteText);
  session.state = 'established';
  var ephText = MS_bytesToHex(session.ephemeral);
