  var shared = MS_hsShared(session, reply.eph);
  var myText = MS_bytesToHex(session.ephemeral);
  var expected = MS_mac(shared, [MS_toBytes(reply.id), MS_toBytes(reply.eph), MS_toBytes(myText)]);
  if (!MS_constantTimeEqual(expected, MS_hexToBytes(reply.mac))) return { ok: false, reason: 'MS:reply-mac' };
