  if (envelope.id !== session.id) throw new Error('MS:envelope-session');
  if (envelope.epoch !== session.epoch) throw new Error('MS:envelope-epoch');
  var chain = MS_chainKey(session, envelope.counter);
  var expected = MS_mac(chain, [MS_toBytes(envelope.id), MS_toBytes(envelope.body), MS_toBytes(String(envelope.counter))]);
  if (!MS_constantTimeEqual(expected, MS_hexToBytes(envelope.tag))) throw new Error('MS:envelope-tag');
